import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    matrix = []
    index = 1

    for i in range(n):
        row = list(map(int, data[index:index + n]))
        matrix.append(row)
        index += n

    count_pattern1 = 0
    count_pattern2 = 0

    for i in range(n):
        for j in range(n):
            expected1 = (i + j) % 2
            expected2 = 1 - expected1

            if matrix[i][j] != expected1:
                count_pattern1 += 1
            if matrix[i][j] != expected2:
                count_pattern2 += 1

    answer = min(count_pattern1, count_pattern2)
    print(answer)

if __name__ == "__main__":
    main()
